using System.Collections.Generic;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CompanionsTierListsList", menuName = "Data/Battle/Companions/CompanionsTierLists Lists")]
public class CompanionsTierListsList : ScriptableObject
{
	[Header("Lists")]
	[SerializeField]
	private CompanionsTierList[] companionsLists;

	public CompanionsTierList[] CompanionsLists => companionsLists;

	public List<CompanionData> GetCompanionsTierListCompanionDatas(CompanionRarityTier companionRarityTier)
	{
		List<CompanionData> list = new List<CompanionData>();
		for (int i = 0; i < companionsLists.Length; i++)
		{
			for (int j = 0; j < companionRarityTier.CompanionTiers.Length; j++)
			{
				if (companionsLists[i].CompanionTier == companionRarityTier.CompanionTiers[j])
				{
					list.AddRange(companionsLists[i].Companions);
				}
			}
		}
		return list;
	}

	public CompanionsTierList GetCompanionsTierList(CompanionTier companionTier)
	{
		for (int i = 0; i < companionsLists.Length; i++)
		{
			if (companionsLists[i].CompanionTier == companionTier)
			{
				return companionsLists[i];
			}
		}
		return null;
	}

	public CompanionData GetCompanionData(string companionName)
	{
		CompanionData companionData = null;
		for (int i = 0; i < companionsLists.Length; i++)
		{
			companionData = companionsLists[i].GetCompanionData(companionName, logError: false);
			if (companionData != null)
			{
				return companionData;
			}
		}
		return companionData;
	}

	public void ClearModdedCompanions()
	{
		companionsLists.InteractThroughItems(delegate(CompanionsTierList item)
		{
			item.Companions.RemoveNullObjects();
		});
	}
}
